import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BEmfQga0.js";const g=JSON.parse('{"title":"Hook and Proxy Integration","description":"","frontmatter":{},"headers":[],"relativePath":"host-adapter-development/hook-proxy-integration.md","filePath":"host-adapter-development/hook-proxy-integration.md","lastUpdated":1788258471000}'),n={name:"host-adapter-development/hook-proxy-integration.md"};function i(s,e,l,d,h,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="hook-and-proxy-integration" tabindex="-1">Hook and Proxy Integration <a class="header-anchor" href="#hook-and-proxy-integration" aria-label="Permalink to &quot;Hook and Proxy Integration&quot;">​</a></h1><p>TokenPilot uses three integration approaches across its host adapters.</p><h2 id="integration-approaches" tabindex="-1">Integration Approaches <a class="header-anchor" href="#integration-approaches" aria-label="Permalink to &quot;Integration Approaches&quot;">​</a></h2><h3 id="proxy-hooks-codex-cli" tabindex="-1">Proxy + Hooks (Codex CLI) <a class="header-anchor" href="#proxy-hooks-codex-cli" aria-label="Permalink to &quot;Proxy + Hooks (Codex CLI)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: uses Codex config mutation, hook registration, and a local OpenAI-compatible Responses proxy. Preserves the current active Codex provider name and reroutes that provider&#39;s <code>base_url</code> through the local proxy. Hooks registered: <code>SessionStart</code>, <code>PreToolUse</code>, <code>PostToolUse</code>.</p><h3 id="gateway-mcp-sessionstart-claude-code" tabindex="-1">Gateway + MCP + SessionStart (Claude Code) <a class="header-anchor" href="#gateway-mcp-sessionstart-claude-code" aria-label="Permalink to &quot;Gateway + MCP + SessionStart (Claude Code)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: uses local Anthropic-compatible gateway routing plus lightweight hooks for observability. A <code>SessionStart</code> hook auto-starts the local gateway. The <code>tokenpilot_memory_fault_recover</code> MCP server is registered for recovery.</p><h3 id="native-plugin-slot-openclaw" tabindex="-1">Native Plugin Slot (OpenClaw) <a class="header-anchor" href="#native-plugin-slot-openclaw" aria-label="Permalink to &quot;Native Plugin Slot (OpenClaw)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: bundled plugin with embedded runtime. The host delivers events directly to the plugin without an external proxy or gateway. Supports in-host slash commands, lifecycle eviction controls, and <code>mode aggressive</code>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./adapter-architecture">Adapter Architecture</a></li><li><a href="./adding-new-host">Adding a New Host</a></li><li><a href="./configuration-integration">Configuration Integration</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a></li></ul>',11)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
